import { describe, test, expect } from 'bun:test';
import { kw } from './kw.js';
import { aes } from '../cipher/aes.js';
import { bitArray } from '../utils/bitArray.js';
import { hex } from '../../io/codec/hex.js';

const _ba = bitArray.factory();
const _hex = hex.factory();
const _aes = aes.factory();
const _kw = kw.factory(_ba);

const fromHex = (s) => _hex.toBytes(s);
const toHex = (u8) => _hex.fromBytes(u8);
const keyBa = (s) => Array.from(_ba.ui8_to_ba(_hex.toBytes(s)));

describe('kw module (RFC 3394 / RFC 5649)', () => {

    test('module metadata', () => {
        expect(kw.name).toBe('kw');
        expect(kw.dependencies).toEqual(['bitArray']);
    });

    // ── RFC 3394 §4 vectors ───────────────────────────────────────────────

    describe('RFC 3394 §4.1 — Wrap 128-bit key with 128-bit KEK', () => {
        const kek = keyBa('000102030405060708090A0B0C0D0E0F');
        const data = fromHex('00112233445566778899AABBCCDDEEFF');
        const expected = '1FA68B0A8112B447AEF34BD8FB5A7B829D3E862371D2CFE5';

        test('wrap', () => {
            const cipher = _aes.ttable.fn(kek);
            expect(toHex(_kw.wrap(cipher, data)).toUpperCase()).toBe(expected);
        });

        test('unwrap round-trip', () => {
            const cipher = _aes.ttable.fn(kek);
            const wrapped = _kw.wrap(cipher, data);
            expect(toHex(_kw.unwrap(_aes.ttable.fn(kek), wrapped)).toUpperCase()).toBe(toHex(data).toUpperCase());
        });
    });

    describe('RFC 3394 §4.2 — Wrap 128-bit key with 192-bit KEK', () => {
        const kek = keyBa('000102030405060708090A0B0C0D0E0F1011121314151617');
        const data = fromHex('00112233445566778899AABBCCDDEEFF');
        const expected = '96778B25AE6CA435F92B5B97C050AED2468AB8A17AD84E5D';

        test('wrap', () => {
            expect(toHex(_kw.wrap(_aes.ttable.fn(kek), data)).toUpperCase()).toBe(expected);
        });

        test('unwrap', () => {
            expect(toHex(_kw.unwrap(_aes.ttable.fn(kek), fromHex(expected))).toUpperCase())
                .toBe(toHex(data).toUpperCase());
        });
    });

    describe('RFC 3394 §4.3 — Wrap 128-bit key with 256-bit KEK', () => {
        const kek = keyBa('000102030405060708090A0B0C0D0E0F101112131415161718191A1B1C1D1E1F');
        const data = fromHex('00112233445566778899AABBCCDDEEFF');
        const expected = '64E8C3F9CE0F5BA263E9777905818A2A93C8191E7D6E8AE7';

        test('wrap', () => {
            expect(toHex(_kw.wrap(_aes.ttable.fn(kek), data)).toUpperCase()).toBe(expected);
        });
    });

    describe('RFC 3394 §4.4 — Wrap 192-bit key with 192-bit KEK', () => {
        const kek = keyBa('000102030405060708090A0B0C0D0E0F1011121314151617');
        const data = fromHex('00112233445566778899AABBCCDDEEFF0001020304050607');
        const expected = '031D33264E15D33268F24EC260743EDCE1C6C7DDEE725A936BA814915C6762D2';

        test('wrap', () => {
            expect(toHex(_kw.wrap(_aes.ttable.fn(kek), data)).toUpperCase()).toBe(expected);
        });
    });

    describe('RFC 3394 §4.6 — Wrap 256-bit key with 256-bit KEK', () => {
        const kek = keyBa('000102030405060708090A0B0C0D0E0F101112131415161718191A1B1C1D1E1F');
        const data = fromHex('00112233445566778899AABBCCDDEEFF000102030405060708090A0B0C0D0E0F');
        const expected =
            '28C9F404C4B810F4CBCCB35CFB87F8263F5786E2D80ED326CBC7F0E71A99F43BFB988B9B7A02DD21';

        test('wrap', () => {
            expect(toHex(_kw.wrap(_aes.ttable.fn(kek), data)).toUpperCase()).toBe(expected);
        });
    });

    // ── RFC 5649 §6 vectors (KWP) ─────────────────────────────────────────

    describe('RFC 5649 §6 — KWP test vector 1 (20-byte key)', () => {
        const kek = keyBa('5840df6e29b02af1ab493b705bf16ea1ae8338f4dcc176a8');
        const data = fromHex('c37b7e6492584340bed12207808941155068f738');
        const expected = '138bdeaa9b8fa7fc61f97742e72248ee5ae6ae5360d1ae6a5f54f373fa543b6a';

        test('wrapPad', () => {
            expect(toHex(_kw.wrapPad(_aes.ttable.fn(kek), data))).toBe(expected);
        });

        test('unwrapPad', () => {
            expect(toHex(_kw.unwrapPad(_aes.ttable.fn(kek), fromHex(expected)))).toBe(toHex(data));
        });
    });

    describe('RFC 5649 §6 — KWP test vector 2 (7-byte key, single semiblock)', () => {
        const kek = keyBa('5840df6e29b02af1ab493b705bf16ea1ae8338f4dcc176a8');
        const data = fromHex('466f7250617369');
        const expected = 'afbeb0f07dfbf5419200f2ccb50bb24f';

        test('wrapPad', () => {
            expect(toHex(_kw.wrapPad(_aes.ttable.fn(kek), data))).toBe(expected);
        });

        test('unwrapPad', () => {
            expect(toHex(_kw.unwrapPad(_aes.ttable.fn(kek), fromHex(expected)))).toBe(toHex(data));
        });
    });

    describe('error handling', () => {
        const kek = keyBa('000102030405060708090A0B0C0D0E0F');

        test('KW rejects single semiblock (< 16 bytes)', () => {
            expect(_kw.wrap(_aes.ttable.fn(kek), fromHex('0011223344556677'))).toBe(false);
        });

        test('KW rejects non-multiple-of-8 input', () => {
            expect(_kw.wrap(_aes.ttable.fn(kek), fromHex('001122334455'))).toBe(false);
        });

        test('KW unwrap detects tampered ciphertext', () => {
            const data = fromHex('00112233445566778899AABBCCDDEEFF');
            const wrapped = _kw.wrap(_aes.ttable.fn(kek), data);
            wrapped[0] ^= 1;
            expect(_kw.unwrap(_aes.ttable.fn(kek), wrapped)).toBe(false);
        });

        test('KWP rejects empty input', () => {
            expect(_kw.wrapPad(_aes.ttable.fn(kek), new Uint8Array(0))).toBe(false);
        });

        test('KWP unwrap rejects tampered ciphertext', () => {
            const data = fromHex('466f7250617369');
            const wrapped = _kw.wrapPad(_aes.ttable.fn(kek), data);
            wrapped[0] ^= 1;
            expect(_kw.unwrapPad(_aes.ttable.fn(kek), wrapped)).toBe(false);
        });
    });
});


