describe('kw - ACVP-AES-KW-1.0 (cipher variant, sub-sampled 3/group)', () => {

    describe('AFT encrypt (54 vectors / 1800 -- AES-128/192/256 x 6 payloadLen)', () => {
        test.each(KW_AFT_ENC)('tgId=$tg tcId=$tc (AES-$kl, payloadLen=$pl)', (v) => {
            const cipher = _aes.ttable.fn(keyBa(v.key), true);
            const out = _kw.wrap(cipher, fromHex(v.pt));
            expect(out).not.toBe(false);
            expect(toHex(out)).toBe(v.ct.toLowerCase());
        });
    });

    describe('AFT decrypt (54 vectors / 1800 -- AES-128/192/256 x 6 payloadLen)', () => {
        test.each(KW_AFT_DEC)('tgId=$tg tcId=$tc (AES-$kl, payloadLen=$pl)', (v) => {
            const cipher = _aes.ttable.fn(keyBa(v.key), true);
            const out = _kw.unwrap(cipher, fromHex(v.ct));
            if (v.pass) {
                expect(out).not.toBe(false);
                expect(toHex(out)).toBe(v.pt.toLowerCase());
            } else {
                expect(out).toBe(false);
            }
        });
    });

});

