// ============================================================================
// Iteration D2 of the FIPS 140-3 upgrade plan
// ----------------------------------------------------------------------------
// (1) `wrapInverseCipher` / `unwrapInverseCipher`: explicit reject for the
//     SP 800-38F §6.3 KW-AE/AD inverse-cipher variant (CIPH_K^-1 in the
//     wrap direction). Not implemented - avoid any silent usage.
// (2) TDES reject via `_checkPrf`: SP 800-131A §2.4 deprecates 3DES since 2024,
//     SP 800-38F §6.2 mandates AES (16-byte block). Any PRF whose
//     `blockSize !== 16` is rejected.
// ============================================================================

describe('kw - iteration D2: KW-AE inverse + TDES guards', () => {

    test('wrapInverseCipher returns false + warns (NOT-IMPLEMENTED)', () => {
        expect(_kw.wrapInverseCipher()).toBe(false);
    });

    test('unwrapInverseCipher returns false + warns (NOT-IMPLEMENTED)', () => {
        expect(_kw.unwrapInverseCipher()).toBe(false);
    });

    test('wrap rejects PRF with blockSize=8 (TDES)', () => {
        // Mock TDES-shaped PRF : encrypt+decrypt + blockSize=8 (bytes).
        const fakeTdes = {
            blockSize: 8,
            encrypt: () => [0, 0],   // 2-word return = 8 bytes
            decrypt: () => [0, 0]
        };
        const validPt = fromHex('00112233445566778899AABBCCDDEEFF');
        expect(_kw.wrap(fakeTdes, validPt)).toBe(false);
    });

    test('unwrap rejects PRF with blockSize=8 (TDES)', () => {
        const fakeTdes = {
            blockSize: 8,
            encrypt: () => [0, 0],
            decrypt: () => [0, 0]
        };
        const validCt = fromHex('00'.repeat(24));
        expect(_kw.unwrap(fakeTdes, validCt)).toBe(false);
    });

    test('wrapPad rejects PRF with blockSize=8 (TDES)', () => {
        const fakeTdes = {
            blockSize: 8,
            encrypt: () => [0, 0],
            decrypt: () => [0, 0]
        };
        expect(_kw.wrapPad(fakeTdes, fromHex('00112233445566778899AABBCCDDEEFF'))).toBe(false);
    });

    test('AES PRF (no explicit blockSize) still accepted (back-compat)', () => {
        // Real AES cipher doesn't expose .blockSize, so the guard is opt-in.
        const cipher = _aes.ttable.fn(keyBa('000102030405060708090A0B0C0D0E0F'), true);
        const wrapped = _kw.wrap(cipher, fromHex('00112233445566778899AABBCCDDEEFF'));
        expect(wrapped).not.toBe(false);
    });

    test('AES PRF with explicit blockSize=16 (defensive) accepted', () => {
        const inner = _aes.ttable.fn(keyBa('000102030405060708090A0B0C0D0E0F'), true);
        const wrapped = {
            blockSize: 16,
            encrypt: (d) => inner.encrypt(d),
            decrypt: (d) => inner.decrypt(d),
        };
        const out = _kw.wrap(wrapped, fromHex('00112233445566778899AABBCCDDEEFF'));
        expect(out).not.toBe(false);
    });

});
